const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2016-08-01';
  const endDate = '2018-02-28';

  // Get country boundaries from the LSIB dataset.
  const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
  const cambodia = countries.filter(ee.Filter.eq('country_na', 'Cambodia')).geometry();
  const thailand = countries.filter(ee.Filter.eq('country_na', 'Thailand')).geometry();

  // 2. Data Acquisition & Check
  const firmsCollection = ee.ImageCollection('FIRMS')
    .filterDate(startDate, endDate)
    .select('T21'); // T21 is brightness temperature, a proxy for fire presence.

  if (firmsCollection.size().getInfo() === 0) {
    console.log("Evidence: No FIRMS images found for the specified date range.");
    console.log("C1");
    return;
  }

  // Combine into a single image for efficient processing.
  // We use a max reducer because any detection in the time series is a fire.
  const fireImage = firmsCollection.max();

  // 3. Processing: Count fire pixels in each country
  const reduceParams = {
    reducer: ee.Reducer.count(),
    geometry: null, // will be set below
    scale: 1000,
    maxPixels: 1e9
  };

  const cambodiaStats = fireImage.reduceRegion({ ...reduceParams, geometry: cambodia });
  const thailandStats = fireImage.reduceRegion({ ...reduceParams, geometry: thailand });

  // 4. Calculation
  const cambodiaFireCount = cambodiaStats.get('T21').getInfo();
  const thailandFireCount = thailandStats.get('T21').getInfo();

  // 5. Validation & Final Answer
  if (cambodiaFireCount === null || thailandFireCount === null) {
      console.log("Evidence: Failed to calculate fire counts.");
      console.log("C3");
      return;
  }

  if (cambodiaFireCount === 0 && thailandFireCount === 0) {
      console.log("Evidence: No fire pixels were detected in either country for the period.");
      console.log("C2");
      return;
  }

  console.log(`Evidence: Cambodia active fire pixel count: ${cambodiaFireCount}`);
  console.log(`Evidence: Thailand active fire pixel count: ${thailandFireCount}`);

  if (cambodiaFireCount > thailandFireCount) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

